// The answers a socket's short frames get are serialised, so a frame sent after a list cannot be answered before it.
function answerOnSocket(
  ws: WebSocket,
  answers: WeakMap<WebSocket, Promise<void>>,
  answer: () => Promise<void>
): Promise<void> {
  const queued = (answers.get(ws) ?? Promise.resolve()).then(answer);
  // The queue never carries a rejection: this frame's answer is reported by the caller that awaited it.
  answers.set(ws, queued.then(() => undefined, () => undefined));
  return queued;
}
```

