// The list is the socket's own user's: the frame names no user, and one it did name would be read by no one.
async function answerListSessions(
  ws: WebSocket,
  store: SessionStore | undefined,
  userId: string | number,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const listed = await store?.listFor?.(userId, {limit: message.limit, before: message.before});
    sendJson(ws, {type: 'session_list', sessions: (listed ?? []).map(onTheWire)});
  } catch (error) {
    // The store's own words can name a collection or a query; the client gets the failure, the log gets the detail.
    log.error('ws', 'listing conversations failed', {userId, error: messageOf(error)});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
  }
}

