export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  // Keyed by socket: the short answers a socket asks for are serialised, so a frame cannot be answered before the one sent before it.
  const answers = new WeakMap<WebSocket, Promise<void>>();
  return function handleMessage(
    ws: ExtWebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    // A history request is not a turn: it queues on its socket's short answers, never behind a streaming one.
    return wsErrorHandler(ws, () => inArrivalOrder(ws, answers, () => answerFrame(ws, validation, sessionStore)));
  };
}

// A socket's answers go out in the order its frames arrived, and one that fails never poisons the frames behind it.
function inArrivalOrder(
  ws: WebSocket,
  answers: WeakMap<WebSocket, Promise<void>>,
  answer: () => Promise<void>
): Promise<void> {
  const queued = (answers.get(ws) ?? Promise.resolve()).then(answer);
  // The queue keeps no rejection: the frame that failed is answered by whoever awaited it, and the next one runs.
  answers.set(ws, queued.then(() => undefined, () => undefined));
  return queued;
}
```

