export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  // Keyed by socket: the short answers a socket asks for serialise, so a frame is never answered before the one sent before it.
  const answers = new WeakMap<WebSocket, Promise<void>>();
  return function handleMessage(
    ws: ExtWebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, sessionStore, validation, signal));
    }
    // A history request is not a turn: it serialises with this socket's other short answers, never behind a streaming one.
    return answerInOrder(ws, answers, () => answerFrame(ws, validation, sessionStore));
  };
}

// The queue holds no rejection: each frame's answer carries its own error handling, so the frames behind it still run.
function answerInOrder(
  ws: WebSocket,
  answers: WeakMap<WebSocket, Promise<void>>,
  answer: () => Promise<void>
): Promise<void> {
  const queued = (answers.get(ws) ?? Promise.resolve()).then(() => wsErrorHandler(ws, answer));
  answers.set(ws, queued);
  return queued;
}

