  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  return answerFrame(ws, validation, sessionStore);
}

async function answerFrame(ws: ExtWebSocket, validation: ValidationResult, sessionStore: SessionStore): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await answerListSessions(ws, sessionStore, ws.userId, message);
}

// The list is the socket's own user's: the frame names no user, and one it carried would be read by nobody.
async function answerListSessions(
  ws: WebSocket,
  store: SessionStore,
  userId: string | number,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const listed = await store.listFor?.(userId, {limit: message.limit, before: message.before});
    sendJson(ws, {type: 'session_list', sessions: (listed ?? []).map(toSummaryFrame)});
  } catch (error) {
    // A store's own words can name a collection or a query, so the client gets the failure and the log the detail.
    log.error('ws', 'listing conversations failed', {userId, error: messageOf(error)});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
  }
}

// A Date does not survive JSON.stringify as a Date, so the two times travel as ISO strings.
function toSummaryFrame({sessionId, createdAt, updatedAt, entryCount}: SessionSummary): SessionSummaryFrame {
  return {sessionId, createdAt: createdAt.toISOString(), updatedAt: updatedAt.toISOString(), entryCount};
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

