38	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore: SessionStore) {
39	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
40	  const lock = new PerSessionLock();
41	  // Keyed by socket: the short answers a socket asks for serialise, so a frame is never answered before the one sent before it.
42	  const answers = new WeakMap<WebSocket, Promise<void>>();
43	  return function handleMessage(
44	    ws: ExtWebSocket,
45	    session: ChatSession,
46	    rawMessage: unknown,
47	    signal?: AbortSignal
48	  ): Promise<void> {
49	    const validation = validateMessage(rawMessage);
50	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
51	    if (isUserMessageFrame(rawMessage)) {
52	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, sessionStore, validation, signal));
53	    }
54	    // A history request is not a turn: it serialises with this socket's other short answers, never behind a streaming one.
55	    return answerInOrder(ws, answers, () => answerFrame(ws, validation, sessionStore));
56	  };
57	}
