59	// The queue holds no rejection: each frame's answer carries its own error handling, so the frames behind it still run.
60	function answerInOrder(
61	  ws: WebSocket,
62	  answers: WeakMap<WebSocket, Promise<void>>,
63	  answer: () => Promise<void>
64	): Promise<void> {
65	  const queued = (answers.get(ws) ?? Promise.resolve()).then(() => wsErrorHandler(ws, answer));
66	  answers.set(ws, queued);
67	  return queued;
68	}
