70	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
71	async function answerInTurn(
72	  ws: WebSocket,
73	  session: ChatSession,
74	  orchestrator: ChatOrchestrator,
75	  sessionStore: SessionStore,
76	  validation: ValidationResult,
77	  signal: AbortSignal | undefined
78	): Promise<void> {
79	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
80	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
81	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
82	    return;
83	  }
84	  const startedAt = Date.now();
85	  try {
86	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, sessionStore, validation, signal));
87	  } finally {
88	    endTurn(ws, session, signal, startedAt);
89	  }
